var param = {
    "id":"ggb",
    "width":1200,
    "height":500,
    "showToolBar":false,
    "borderColor":null,
    "showMenuBar":false,
    "showAlgebraInput":false,
    "showResetIcon":false,
    "enableLabelDrags":false,
    "enableShiftDragZoom":true,
    "enableRightClick":false,
    "capturingThreshold":null,
    "showToolBarHelp":false,
    "errorDialogsActive":false,
    "useBrowserForJS":true,
    "ggbBase64":""};


    
     var ggbApplet = new GGBApplet(param, '5.0');
    ggbApplet.setHTML5Codebase("/vendor/geogebra/GeoGebra/HTML5/5.0/web3d/");
    window.onload = function() {
    ggbApplet.inject('geogebra','preferHTML5');
    }

    inclinacao = 'a'
    quatrica = 'quadratica'
    plano = 'IP';
    ggbInit = false;

function ggbOnInit(){
    ggb = document.ggb;
    ggb.setVisible('Pyramid', false)
    ggb.setVisible('Archimedean', false)
    ggb.setVisible('Prism', false)
    ggb.enableRightClick(false);
    ggb.enableLabelDrags(false);
    ggb.setValue('t',0);
    ggb.setValue(inclinacao,0);
    setEscala();
    ggbInit = true;
}

function setValorPlano(){
    var valor = document.getElementById('valorRange');
    var range = document.getElementById('range');
    valor.innerHTML = range.value;
    if(ggbInit)
        ggb.setValue('t',range.value);
}

function setInclinacaoPlano(){
    var valor = document.getElementById('valorRangeI');
    var range = document.getElementById('rangeI');
    valor.innerHTML = range.value;
    if(ggbInit)
        ggb.setValue('a',range.value);
}
function setEscala(){
    ggb.setCoordSystem(-6,6,-6,6,-6,6);
    ggb.setCoordSystem(-6.5,6.5,-6.5,6.5);
}